.modele-soa.document-pv_modules{font-family:Arial,sans-serif}.modele-soa.document-pv_modules .document-header{margin:0 0 2mm}.modele-soa.document-pv_modules .official-headings{font-size:7px;line-height:1.15;margin:0}.modele-soa.document-pv_modules .branding-row{min-height:15mm;gap:3mm}.modele-soa.document-pv_modules .campus-logo-block,.modele-soa.document-pv_modules .tutelle-logos{flex-basis:20mm}.modele-soa.document-pv_modules .campus-logo{max-width:18mm;max-height:15mm}.modele-soa.document-pv_modules .branding-title strong{font-size:12px}.modele-soa.document-pv_modules .branding-title span{font-size:7px}.modele-soa.document-pv_modules .tutelle-logos img{max-width:12mm;max-height:14mm}.modele-soa.document-pv_modules .school{margin:1mm;font-size:7px;line-height:1.15}.modele-soa.document-pv_modules .school span{font-size:7px}.modele-soa.document-pv_modules h2{font-size:10px;margin:1mm 0}.modele-soa.document-pv_modules .context{font-size:7px;line-height:1.2;margin:1mm 0 2mm}.soa-pv-modules{break-inside:avoid;page-break-inside:avoid}.soa-pv-modules h3{text-align:center;font-size:7px;margin:1mm 0;text-transform:uppercase}.soa-pv-legend,.soa-pv-matrix{width:100%;table-layout:fixed;border-collapse:collapse;margin:0}.soa-pv-legend{font-size:6px;margin-bottom:2mm}.soa-pv-legend td{width:33.333%;border:1px solid #555;padding:1px 2px;text-align:left;line-height:1.08}.soa-pv-legend small{font-size:5px;white-space:nowrap}.soa-pv-matrix{font-size:{{ count($sessions)>25?5:6 }}px}.soa-pv-matrix th,.soa-pv-matrix td{border:1px solid #222;padding:1px;text-align:center;line-height:1.05;overflow-wrap:anywhere}.soa-pv-matrix th{font-size:{{ count($sessions)>25?5:6 }}px}.soa-pv-matrix .soa-pv-name{text-align:left}.soa-pv-matrix .soa-pv-group-heading{background:#ddd;font-weight:bold}.soa-pv-matrix .soa-pv-group-average{font-weight:bold}.soa-pv-matrix .soa-pv-no-grade{color:#ef8400;font-weight:bold;background:#fff8e8}.soa-pv-matrix .soa-pv-decision{font-weight:bold;font-size:5px}.soa-pv-valid{color:#08752c}.soa-pv-fail{color:#c00000}.soa-pv-signatures{display:flex;justify-content:space-between;margin-top:4mm;font-size:7px;font-weight:bold;text-align:center}.soa-pv-signatures span{width:33%}.modele-soa.document-pv_modules .notice,.modele-soa.document-pv_modules .document-footer{display:none}
@page{size:A3 landscape;margin:8mm 10mm 12mm}
@media print{.modele-soa.document-pv_modules .individual,.soa-pv-modules{break-inside:avoid;page-break-inside:avoid}.soa-pv-matrix tr{break-inside:avoid;page-break-inside:avoid}}
